variants.code_sketch:
abstract record Expr;
sealed record Lit(decimal Value) : Expr;
sealed record Add(Expr L, Expr R) : Expr;

static decimal Eval(Expr e) => e switch
{
    Lit l                      => l.Value,
    Add { L: var l, R: var r } => Eval(l) + Eval(r),
    _ => throw new InvalidOperationException(nameof(e))   // CS8509 if a case is missing
};
